from collections import Counter

def solve_with_all_corners(grid):
    h, w = len(grid), len(grid[0])

    all_vals = [v for r in grid for v in r]
    bg_val = max(set(all_vals), key=lambda k: all_vals.count(k))

    h_markers = []
    for r in range(h):
        non_bg = sum(1 for c in range(w) if grid[r][c] != bg_val)
        if non_bg > w/2:
            h_markers.append(r)

    v_markers = []
    for c in range(w):
        non_bg = sum(1 for r in range(h) if grid[r][c] != bg_val)
        if non_bg > h/2:
            v_markers.append(c)

    corners = {}
    for i, r in enumerate(h_markers):
        for j, c in enumerate(v_markers):
            corners[(i,j)] = grid[r][c]

    all_c = list(corners.values())
    counts = Counter(all_c)
    primary = max(counts.keys(), key=lambda k: counts[k])

    h_out = len(h_markers) - 1
    w_out = len(v_markers) - 1

    output = []
    for i in range(h_out):
        row_data = []
        for j in range(w_out):
            vals = [
                corners[(i, j)],       # Top-left
                corners[(i, j + 1)],   # Top-right  
                corners[(i + 1, j)],   # Bottom-left  
                corners[(i + 1, j + 1)] # Bottom-right
            ]
            if all(v == primary for v in vals):
                row_data.append(primary)
            else:
                row_data.append(6)
        output.append(row_data)

    return output

# Apply to Test Input
test_in = load()['Test input']
output_test = solve_with_all_corners(test_in)
print("Output with 'all 4 corners uniform' rule:")
for row in output_test:
    print(row)
